/* @autogenerated */
// Se carga con `import()` desde InstrumentationService solo cuando hay `telemetry.name`
// en la configuración: todo el SDK de OpenTelemetry queda fuera del bundle inicial.
import { registerInstrumentations } from '@opentelemetry/instrumentation';
import { WebTracerProvider, BatchSpanProcessor, type SpanProcessor } from '@opentelemetry/sdk-trace-web';
import { DocumentLoadInstrumentation } from '@opentelemetry/instrumentation-document-load';
import { FetchInstrumentation } from '@opentelemetry/instrumentation-fetch';
import { XMLHttpRequestInstrumentation } from '@opentelemetry/instrumentation-xml-http-request';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-http';
import { BatchLogRecordProcessor, LoggerProvider } from '@opentelemetry/sdk-logs';
import { OTLPLogExporter } from '@opentelemetry/exporter-logs-otlp-http';
import { Resource, resourceFromAttributes } from '@opentelemetry/resources';
import { ATTR_SERVICE_NAME, ATTR_SERVICE_VERSION } from '@opentelemetry/semantic-conventions';
import { ZoneContextManager } from '@opentelemetry/context-zone';
import type { TelemetryConfig } from '@shared/context/config/app-config.model';
import type { LogLevel, LogRecord, LogSink } from './logger.service';

// SeverityNumber de OpenTelemetry (DEBUG, INFO, WARN, ERROR)
const SEVERITY_NUMBER: Record<LogLevel, number> = { debug: 5, info: 9, warn: 13, error: 17 };

// Atributos aún "incubating" en semantic-conventions: se copian en lugar de importar `/incubating`
const ATTR_DEPLOYMENT_ENVIRONMENT_NAME = 'deployment.environment.name';
const ATTR_SESSION_ID = 'session.id';
const ATTR_APP_TENANT = 'app.tenant';

export interface TelemetryContext {
  /** Versión de build (`environment.version`). */
  version?: string;
  /** Identificador aleatorio de la pestaña. */
  sessionId: string;
  /** Tenant activo en el momento de abrir cada span. */
  tenant: () => string | undefined;
}

export interface TelemetryHandles {
  /** Destino de Logger hacia el colector; solo si hay `telemetry.exporter.logger`. */
  logSink?: LogSink;
}

export function startTelemetry(conf: TelemetryConfig, context: TelemetryContext): TelemetryHandles {
  // Nunca datos personales (email, nombre…): solo lo necesario para agrupar y filtrar
  const resource = resourceFromAttributes({
    [ATTR_SERVICE_NAME]: conf.name,
    [ATTR_SERVICE_VERSION]: context.version,
    [ATTR_DEPLOYMENT_ENVIRONMENT_NAME]: conf.environment,
    [ATTR_SESSION_ID]: context.sessionId,
  });
  if (conf.exporter?.tracer) {
    registerSpan(conf, resource, context);
  }
  return conf.exporter?.logger ? { logSink: registerLogger(conf, resource) } : {};
}

function registerSpan(conf: TelemetryConfig, resource: Resource, context: TelemetryContext) {
  const provider = new WebTracerProvider({
    resource,
    spanProcessors: [
      tenantSpanProcessor(context.tenant),
      new BatchSpanProcessor(new OTLPTraceExporter(conf.exporter!.tracer)),
    ],
  });
  provider.register({
    contextManager: new ZoneContextManager(),
  });
  registerInstrumentations({
    instrumentations: [
      new DocumentLoadInstrumentation(),
      new FetchInstrumentation(),
      new XMLHttpRequestInstrumentation(),
    ],
  });
}

/** El tenant puede cambiar durante la sesión: se pone en cada span, no en el Resource. */
export function tenantSpanProcessor(tenant: () => string | undefined): SpanProcessor {
  return {
    onStart: (span) => {
      const current = tenant();
      if (current) {
        span.setAttribute(ATTR_APP_TENANT, current);
      }
    },
    onEnd: () => {},
    forceFlush: () => Promise.resolve(),
    shutdown: () => Promise.resolve(),
  };
}

function registerLogger(conf: TelemetryConfig, resource: Resource): LogSink {
  const loggerProvider = new LoggerProvider({
    resource,
    processors: [
      new BatchLogRecordProcessor({
        exporter: new OTLPLogExporter(conf.exporter!.logger),
        maxExportBatchSize: 100, // Máximo número de logs por lote
        scheduledDelayMillis: 5000, // Tiempo máximo de espera para enviar un lote (en ms)
        exportTimeoutMillis: 30000, // Tiempo máximo permitido para exportar un lote
      }),
    ],
  });
  const logger = loggerProvider.getLogger('app-logger');

  // Los registros llegan ya redactados desde Logger
  return (record: LogRecord) => {
    logger.emit({
      body: record.message,
      severityText: record.level.toUpperCase(),
      severityNumber: SEVERITY_NUMBER[record.level],
      attributes: {
        timestamp: record.timestamp,
        ...(record.args.length ? { 'log.args': safeStringify(record.args) } : {}),
      },
    });
  };
}

function safeStringify(value: unknown): string {
  const seen = new WeakSet();
  return JSON.stringify(value, (_key, item) => {
    if (typeof item === 'object' && item !== null) {
      if (seen.has(item)) {
        return '[Circular]';
      }
      seen.add(item);
    }
    return item;
  });
}
